package com.adc.infrastructure;

import com.adc.domain.shared.BusinessTime;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Read-only business source queries. No state changes or automatic absence classification. */
@Repository
public class AnalyticsStore {
    private final JdbcTemplate db;public AnalyticsStore(JdbcTemplate db){this.db=db;}
    public record Selection(String metric,Instant start,Instant end,Instant cutoff,List<Long> clinics,Long treatment,Long dentist){}
    private static LocalDateTime utc(Instant at){return LocalDateTime.ofInstant(at,ZoneOffset.UTC);}
    private static String placeholders(Collection<?> values){return String.join(",",Collections.nCopies(values.size(),"?"));}
    private List<Map<String,Object>> query(String sql,List<Object> args){return db.query(sql,(r,n)->{var row=new LinkedHashMap<String,Object>();var meta=r.getMetaData();for(int i=1;i<=meta.getColumnCount();i++){Object value=r.getObject(i);if(value instanceof LocalDateTime time)value=time.toInstant(ZoneOffset.UTC).toString();else if(value instanceof Timestamp time)value=time.toInstant().toString();else if(value instanceof java.sql.Date date)value=date.toLocalDate().toString();else if(value instanceof java.sql.Time time)value=time.toLocalTime().toString();else if(value instanceof Number number)value=number.toString();row.put(meta.getColumnLabel(i),value);}return row;},args.toArray());}
    public boolean historicalStateUnavailable(Selection s){List<String> actions=switch(s.metric){case "treatment-comparison","traceability"->List.of("correctTreatmentPrice");case "skill-slot-coverage","skill-structure"->List.of("maintainDentistAssignment","maintainDentistQualification","setTreatmentRequirements","suspendSchedule","updateDentist","updateQualification","updateTreatment");case "performance","calculation-time"->List.of("publishQuarterPerformance");default->List.of("suspendSchedule");};var args=new ArrayList<Object>();args.add(utc(Set.of("skill-slot-coverage","skill-structure").contains(s.metric)?(s.start.isBefore(s.cutoff)?s.start:s.cutoff):s.cutoff));args.addAll(actions);args.add(tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(s.clinics.stream().map(String::valueOf).toList()));return db.queryForObject("SELECT COUNT(*) FROM adc_audit.AuditEvent WHERE occurred_at>? AND result='SUCCESS' AND action IN ("+placeholders(actions)+") AND (JSON_OVERLAPS(clinic_scope,CAST(? AS JSON)) OR object_kind IN ('Treatment','Qualification'))",Integer.class,args.toArray())>0;}
    public List<Map<String,Object>> appointments(Selection s){var args=new ArrayList<Object>(s.clinics);args.add(utc(s.start));args.add(utc(s.end));args.add(utc(s.cutoff));String filter="";if(s.dentist!=null){filter=" AND a.dentist_id=?";args.add(s.dentist);}return query("SELECT a.appointment_id,a.clinic_id,a.dentist_id,a.scheduled_at,a.created_at,a.cancelled_at,a.cancellation_kind,s.slot_minutes FROM adc_business.Appointment a JOIN adc_business.DentistSchedule s ON s.schedule_id=a.schedule_id WHERE a.clinic_id IN ("+placeholders(s.clinics)+") AND a.scheduled_at>=? AND a.scheduled_at<? AND a.created_at<=?"+filter+" ORDER BY a.appointment_id",args);}
    public List<Map<String,Object>> events(long appointment,Instant cutoff){return query("SELECT event_type,to_status,occurred_at FROM adc_business.AppointmentEvent WHERE appointment_id=? AND occurred_at<=? ORDER BY occurred_at,CASE event_type WHEN 'BOOK' THEN 0 WHEN 'ATTEND' THEN 1 WHEN 'CANCEL' THEN 1 WHEN 'COMPLETE' THEN 2 WHEN 'INVOICE' THEN 3 END",List.of(appointment,utc(cutoff)));}
    public List<Map<String,Object>> treatments(Selection s){var args=new ArrayList<Object>(s.clinics);args.add(utc(s.start));args.add(utc(s.end));args.add(utc(s.cutoff));String filter="";if(s.treatment!=null){filter+=" AND t.treatment_id=?";args.add(s.treatment);}if(s.dentist!=null){filter+=" AND t.dentist_id=?";args.add(s.dentist);}return query("SELECT t.applied_treatment_id,t.appointment_id,a.patient_id,t.dentist_id,t.treatment_id,t.standard_units,t.unit_price,t.subtotal,t.performed_at,a.clinic_id FROM adc_business.AppliedTreatment t JOIN adc_business.Appointment a ON a.appointment_id=t.appointment_id WHERE a.clinic_id IN ("+placeholders(s.clinics)+") AND t.performed_at>=? AND t.performed_at<? AND t.performed_at<=?"+filter+" ORDER BY t.applied_treatment_id",args);}
    public List<Map<String,Object>> schedules(Selection s){var args=new ArrayList<Object>(s.clinics);args.add(s.start.atZone(BusinessTime.ZONE).toLocalDate());args.add(s.end.atZone(BusinessTime.ZONE).toLocalDate());args.add(utc(s.cutoff));String filter="";if(s.dentist!=null){filter=" AND dentist_id=?";args.add(s.dentist);}return query("SELECT schedule_id,dentist_id,clinic_id,schedule_date,start_time,end_time,slot_minutes FROM adc_business.DentistSchedule WHERE clinic_id IN ("+placeholders(s.clinics)+") AND schedule_date>=? AND schedule_date<=? AND created_at<=? AND schedule_status='NORMAL'"+filter+" ORDER BY schedule_id",args);}
    public boolean qualified(long dentist,long clinic,LocalDate date,long treatment){return db.queryForObject("SELECT COUNT(*) FROM adc_business.Dentist d WHERE d.dentist_id=? AND d.is_active=true AND d.hire_date<=? AND (d.termination_date IS NULL OR d.termination_date>=?) AND EXISTS(SELECT 1 FROM adc_business.DentistClinicAssignment a WHERE a.dentist_id=d.dentist_id AND a.clinic_id=? AND a.is_active=true AND a.start_date<=? AND (a.end_date IS NULL OR a.end_date>=?)) AND NOT EXISTS(SELECT 1 FROM adc_business.TreatmentQualification q LEFT JOIN adc_business.Qualification catalog ON catalog.qualification_id=q.qualification_id WHERE q.treatment_id=? AND q.is_mandatory=true AND (catalog.is_active=false OR NOT EXISTS(SELECT 1 FROM adc_business.DentistQualification p WHERE p.dentist_id=d.dentist_id AND p.qualification_id=q.qualification_id AND p.verification_status='VERIFIED' AND p.granted_date<=? AND (p.expiry_date IS NULL OR p.expiry_date>=?))))",Integer.class,dentist,date,date,clinic,date,date,treatment,date,date)==1;}
    public boolean treatmentExists(long treatment){return db.queryForObject("SELECT COUNT(*) FROM adc_business.Treatment WHERE treatment_id=?",Integer.class,treatment)==1;}
    public Map<String,Object> skillEvidence(Selection s){var args=new ArrayList<Object>(s.clinics);var personnel=query("SELECT d.dentist_id,d.hire_date,d.termination_date,d.is_active AS employment_active,a.assignment_id,a.clinic_id,a.start_date,a.end_date,a.is_active AS assignment_active,q.qualification_id,q.granted_date,q.expiry_date,q.verification_status,c.is_active AS qualification_active FROM adc_business.Dentist d JOIN adc_business.DentistClinicAssignment a ON a.dentist_id=d.dentist_id LEFT JOIN adc_business.DentistQualification q ON q.dentist_id=d.dentist_id LEFT JOIN adc_business.Qualification c ON c.qualification_id=q.qualification_id WHERE a.clinic_id IN ("+placeholders(s.clinics)+") ORDER BY d.dentist_id,a.assignment_id,q.qualification_id",args);var requirements=s.treatment==null?List.of():query("SELECT treatment_id,qualification_id,is_mandatory FROM adc_business.TreatmentQualification WHERE treatment_id=? ORDER BY qualification_id",List.of(s.treatment));return Map.of("personnel_qualification_basis",personnel,"treatment_requirements",requirements);}
    public List<Map<String,Object>> qualifications(Selection s){var args=new ArrayList<Object>(s.clinics);var first=s.start.atZone(BusinessTime.ZONE).toLocalDate();var last=s.end.minusNanos(1).atZone(BusinessTime.ZONE).toLocalDate();args.add(first);for(int i=0;i<4;i++)args.add(last);String filter="";if(s.dentist!=null){filter=" AND q.dentist_id=?";args.add(s.dentist);}return query("SELECT DISTINCT q.dentist_id,q.qualification_id,q.granted_date,q.expiry_date,q.verification_status FROM adc_business.DentistQualification q JOIN adc_business.DentistClinicAssignment a ON a.dentist_id=q.dentist_id JOIN adc_business.Dentist d ON d.dentist_id=q.dentist_id JOIN adc_business.Qualification catalog ON catalog.qualification_id=q.qualification_id WHERE a.clinic_id IN ("+placeholders(s.clinics)+") AND a.is_active=true AND d.is_active=true AND catalog.is_active=true AND q.verification_status='VERIFIED' AND GREATEST(q.granted_date,a.start_date,d.hire_date,?)<=LEAST(COALESCE(q.expiry_date,?),COALESCE(a.end_date,?),COALESCE(d.termination_date,?),?)"+filter+" ORDER BY q.dentist_id,q.qualification_id",args);}
    public long patientUsage(long clinic,Selection s){return db.queryForObject("SELECT COUNT(*) FROM adc_audit.AuditEvent WHERE result='SUCCESS' AND action IN ('createPatient','lookupPatient','getPatient') AND JSON_CONTAINS(clinic_scope,JSON_QUOTE(?)) AND occurred_at>=? AND occurred_at<? AND occurred_at<=?",Long.class,Long.toString(clinic),utc(s.start),utc(s.end),utc(s.cutoff));}
}
